function i(n){if(!n)return"—";const r=Date.parse(n);if(Number.isNaN(r))return"—";const t=Math.round((Date.now()-r)/1e3);if(t<0||t<45)return"just now";if(t<90)return"1m ago";const e=Math.round(t/60);if(e<60)return`${e}m ago`;const u=Math.round(e/60);if(u<24)return`${u}h ago`;const o=Math.round(u/24);if(o<30)return`${o}d ago`;const a=Math.round(o/30);return a<12?`${a}mo ago`:`${Math.round(a/12)}y ago`}function s(n){if(!n)return"—";const r=Date.parse(n);if(Number.isNaN(r))return"—";const t=Math.round((r-Date.now())/1e3);if(t<=0)return"expired";if(t<60)return`in ${t}s`;const e=Math.round(t/60);if(e<60)return`in ${e}m`;const u=Math.round(e/60);if(u<24)return`in ${u}h`;const o=Math.round(u/24);return o<30?`in ${o}d`:`in ${Math.round(o/30)}mo`}function f(n){if(!n)return"—";const r=Date.parse(n);if(Number.isNaN(r))return"—";const t=Math.max(0,Math.round((Date.now()-r)/1e3));if(t<60)return"just now";const e=Math.round(t/60);if(e<60)return`${e}m`;const u=Math.round(e/60);if(u<24)return`${u}h`;const o=Math.round(u/24);return o<30?`${o}d`:`${Math.round(o/30)}mo`}function d(n){if(!n)return"";const r=new Date(n);return Number.isNaN(r.getTime())?"":r.toISOString().replace("T"," ").replace(/\.\d+Z$/," UTC")}export{d as a,f as e,i as r,s as t};
